import { describe, expect, it } from "vitest";
import { parseIniToConfig } from "../src/index.js";

describe("parseIniToConfig · rulesets → schema v2", () => {
  it("parses geosite / geoip / final / provider ruleset lines with sections", () => {
    const ini = [
      "; Generated by ClashRouteKit",
      "[custom]",
      "custom_proxy_group=AI`select`[]DIRECT",
      "custom_proxy_group=Proxy`select`[]DIRECT",
      "custom_proxy_group=Direct`select`[]DIRECT",
      "; 海外类目",
      "ruleset=AI,[]GEOSITE,openai",
      "ruleset=Proxy,[]GEOIP,telegram,no-resolve",
      "ruleset=Direct,[]GEOIP,cn",
      "ruleset=AI,clash-domain:https://raw.example/x/publish/rules/AI_Domain.yaml,28800",
      "ruleset=AI,[]FINAL",
      "",
    ].join("\n");

    const out = parseIniToConfig(ini);

    expect(out.routes).toEqual([
      {
        id: "openai",
        policy: { group: "ai" },
        source: { type: "geosite", value: "openai" },
        section: "海外类目",
      },
      {
        id: "geoip-telegram",
        policy: { group: "proxy" },
        source: { type: "geoip", value: "telegram", noResolve: true },
      },
      {
        id: "geoip-cn",
        policy: { group: "direct" },
        source: { type: "geoip", value: "cn" },
      },
      {
        id: "ai_domain-2",
        policy: { group: "ai" },
        source: { type: "rule-provider", provider: "ai_domain" },
      },
      {
        id: "final",
        policy: { group: "ai" },
        source: { type: "final" },
      },
    ]);
    // 占位 provider：enabled: false、空 sources，待规则库绑定数据源
    expect(out.placeholderProviders).toEqual([
      {
        id: "ai_domain",
        name: "AI_Domain",
        output: "AI_Domain.yaml",
        behavior: "domain",
        enabled: false,
        sources: [],
      },
    ]);
    expect(out.warnings).toEqual([]);
  });

  it("normalizes .mrs ruleset keys to the same-stem .yaml and warns", () => {
    // 上游（如 Aethersailor）模板开始引用编译产物 .mrs；file 只是关联键，
    // 数据一律来自 config 声明的 vendor 源，故按同 stem 归一为 .yaml 键。
    const out = parseIniToConfig(
      [
        "[custom]",
        "ruleset=🎯 全球直连,clash-domain:https://cdn.jsdelivr.net/gh/Aethersailor/Custom_OpenClash_Rules@main/rule/Custom_Direct_Domain.mrs,1800",
        "",
      ].join("\n"),
    );

    expect(out.routes[0]?.source).toEqual({
      type: "rule-provider",
      provider: "custom_direct_domain",
    });
    expect(out.placeholderProviders).toEqual([
      {
        id: "custom_direct_domain",
        name: "Custom_Direct_Domain",
        output: "Custom_Direct_Domain.yaml",
        behavior: "domain",
        enabled: false,
        sources: [],
      },
    ]);
    // 键归一不是静默改写：warning 须点名原始 .mrs 引用
    expect(out.warnings.some((w) => w.includes("Custom_Direct_Domain.mrs"))).toBe(true);
  });

  it("warns and drops per-route intervals that differ from the effective default", () => {
    const out = parseIniToConfig(
      "[custom]\nruleset=AI,clash-domain:https://raw.example/AI_Domain.yaml,1800\n",
    );
    expect(out.routes[0]?.source).toEqual({ type: "rule-provider", provider: "ai_domain" });
    expect(out.warnings.some((w) => w.includes("per-route interval 1800"))).toBe(true);
  });
});

describe("parseIniToConfig · proxy groups → schema v2", () => {
  it("parses select groups with builtin members, group refs, and node filters", () => {
    const out = parseIniToConfig(
      "custom_proxy_group=AI`select`[]DIRECT`[]Proxy`.*\n" +
        "custom_proxy_group=Proxy`select`[]DIRECT\n",
    );
    expect(out.proxyGroups).toEqual([
      {
        id: "ai",
        name: "AI",
        type: "select",
        members: [{ builtin: "DIRECT" }, { group: "proxy" }],
        nodeFilters: [{ match: ".*" }],
      },
      {
        id: "proxy",
        name: "Proxy",
        type: "select",
        members: [{ builtin: "DIRECT" }],
      },
    ]);
    expect(out.memberSets).toEqual({});
  });

  it("parses test-type groups with url, interval and tolerance", () => {
    const out = parseIniToConfig(
      "custom_proxy_group=🇭🇰`url-test`!!GROUPID=0!!(港|HK)`https://cp.cloudflare.com/generate_204`300,,50\n",
    );
    expect(out.proxyGroups[0]).toEqual({
      id: "group-1",
      name: "🇭🇰",
      type: "url-test",
      members: [],
      nodeFilters: [{ match: "!!GROUPID=0!!(港|HK)" }],
      url: "https://cp.cloudflare.com/generate_204",
      interval: 300,
      timeout: null,
      tolerance: 50,
    });
  });

  it("extracts duplicated members into memberSets and presets", () => {
    const out = parseIniToConfig(
      [
        "custom_proxy_group=A`select`[]DIRECT`[]B",
        "custom_proxy_group=B`select`[]DIRECT",
        "custom_proxy_group=C`select`[]DIRECT`[]B",
        "custom_proxy_group=D`select`[]DIRECT",
      ].join("\n"),
    );
    // A/C（[DIRECT, group:b]）与 B/D（[DIRECT]）各成一组重复，提取为 set-1 / set-2，
    // 四个组的 members 全部改为 preset 引用。
    const setEntries = Object.entries(out.memberSets);
    expect(setEntries).toHaveLength(2);
    const [set1Id, set1] = setEntries[0];
    const [set2Id, set2] = setEntries[1];
    expect(set1Id).toBe("set-1");
    expect(set1.members).toEqual([{ builtin: "DIRECT" }, { group: "b" }]);
    expect(set2Id).toBe("set-2");
    expect(set2.members).toEqual([{ builtin: "DIRECT" }]);
    const byName = new Map(out.proxyGroups.map((group) => [group.name, group]));
    expect(byName.get("A")?.members).toEqual([{ preset: "set-1" }]);
    expect(byName.get("C")?.members).toEqual([{ preset: "set-1" }]);
    expect(byName.get("B")?.members).toEqual([{ preset: "set-2" }]);
    expect(byName.get("D")?.members).toEqual([{ preset: "set-2" }]);
  });

  it.each([
    ["300", { interval: 300, timeout: null, tolerance: null }],
    ["300,5", { interval: 300, timeout: 5, tolerance: null }],
    ["300,,50", { interval: 300, timeout: null, tolerance: 50 }],
    ["300,5,50", { interval: 300, timeout: 5, tolerance: 50 }],
  ])("parses health-check tail %s", (tail, expected) => {
    const out = parseIniToConfig(
      `custom_proxy_group=Auto\`url-test\`.*\`https://probe.example/204\`${tail}\n`,
    );

    expect(out.proxyGroups[0]).toMatchObject(expected);
  });
});

describe("parseIniToConfig · unresolvable references", () => {
  it("keeps dangling policy refs and drops unknown members with warnings", () => {
    const out = parseIniToConfig(
      [
        "custom_proxy_group=A`select`[]DIRECT`[]未知组",
        "ruleset=缺失组,[]FINAL",
        "ruleset=AI,clash-domain:https://raw.example/AI_Domain.yaml,28800",
      ].join("\n"),
    );
    expect(out.proxyGroups[0]?.members).toEqual([{ builtin: "DIRECT" }]);
    expect(out.warnings.some((w) => w.includes("未知组"))).toBe(true);
    // 中文显示名 slug 后为空，回退 missing-policy
    expect(out.routes[0]?.policy).toEqual({ group: "missing-policy" });
    expect(out.warnings.some((w) => w.includes("缺失组"))).toBe(true);
    // 与默认 interval 一致时不告警
    expect(out.warnings.some((w) => w.includes("per-route interval"))).toBe(false);
  });
});
